package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.internal.*;import javax.swing.*;import java.awt.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.*;
public final class PopupWorkflowTest extends WorkbenchTest {
 public static void main(String[] args)throws Exception {
  ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->def(m));WorkbenchExtension ext=new WorkbenchExtension();ext.initialize((MontoyaApi)PayloadIntegrationTest.host(MontoyaApi.class));importTraffic(ext,request("https://popup.test/api","GET",true,List.of()),response(200,"{\"ok\":true}"));JTabbedPane tabs=(JTabbedPane)get(ext,"tabs");JTable traffic=(JTable)get(ext,"logTable");Component scope=(Component)get(ext,"scopeContent"),settings=(Component)get(ext,"commonSettingsContent");AtomicInteger scopeCalls=new AtomicInteger(),settingsCalls=new AtomicInteger(),changes=new AtomicInteger();
  ext.dialogOpener=(owner,title,content,modal,closed)->{check(!modal,"popup is modeless so original page remains usable");if(title.contains("SCOPE")){scopeCalls.incrementAndGet();check(content==scope,"scope controls hosted in separate window");}else{settingsCalls.incrementAndGet();check(content==settings,"settings controls hosted in separate window");}return null;};
  edt(()->{traffic.setRowSelectionInterval(0,0);Object current;try{current=get(ext,"current");}catch(Exception ex){throw new RuntimeException(ex);}JButton scopeButton=(JButton)UiLayoutTest.named((Component)unchecked(ext,"root"),"wb.traffic.scope.list");scopeButton.doClick();check(tabs.getSelectedIndex()==0&&traffic.getSelectedRow()==0&&unchecked(ext,"current")==current,"scope button keeps traffic selection and request preview");check(!SwingUtilities.isDescendingFrom(scope,(Component)unchecked(ext,"root")),"scope list no longer replaces traffic pane");
   tabs.setSelectedIndex(3);tabs.addChangeListener(e->changes.incrementAndGet());tabs.setSelectedIndex(tabs.indexOfTab("설정"));check(tabs.getSelectedIndex()==3&&changes.get()==0,"settings opens without any temporary tab change");tabs.setSelectedIndex(tabs.indexOfTab("설정"));check(tabs.getSelectedIndex()==3&&settingsCalls.get()==2,"repeated settings action keeps original page");
   scopeButton.doClick();check(tabs.getSelectedIndex()==3&&changes.get()==0,"scope window never forces navigation to traffic");
   tabs.setSelectedIndex(2);JTabbedPane data=(JTabbedPane)unchecked(ext,"dataTabs");data.setSelectedIndex(2);changes.set(0);tabs.setSelectedIndex(tabs.indexOfTab("설정"));check(tabs.getSelectedIndex()==2&&data.getSelectedIndex()==2&&changes.get()==0,"settings preserves nested data tool selection");
   tabs.setSelectedIndex(tabs.indexOfTab("점검 진행 현황"));int activity=tabs.getSelectedIndex();changes.set(0);tabs.setSelectedIndex(tabs.indexOfTab("설정"));check(tabs.getSelectedIndex()==activity&&changes.get()==0,"settings preserves activity tracking screen");
  });check(scopeCalls.get()==2&&settingsCalls.get()==4,"both popup entry points invoke correct window actions");check(PayloadIntegrationTest.sent.get()==0,"opening popups sends no HTTP traffic");for(var h:PayloadIntegrationTest.modernUnloads)h.extensionUnloaded();edt(()->{});System.out.println("PopupWorkflowTest: "+checks+" checks passed");
 }
 static Object unchecked(Object o,String name){try{return get(o,name);}catch(Exception e){throw new RuntimeException(e);}}
}
